            }
        }
        self.agent_pane_ids.retain(|tid, _| agent_ids.contains(tid));

        self.agent_labels.retain(|tid, _| agent_ids.contains(tid));
        for tid in agent_ids {
            if !self.agent_labels.contains_key(&tid) {
                self.next_agent += 1;
                self.agent_labels
