    /// Defensive: a missing or malformed file leaves the map untouched.
    fn read_agent_labels(&mut self) {
        let Ok(body) = fs::read_to_string(AGENT_LABELS_PATH) else {
            return;
        };
        for (tid, label) in parse_agent_labels(&body) {
