156	/// `panopt _process-run` - run a process instance in the current pane.
157	///
158	/// This is the edge effector of the instance lifecycle (todo #141): the cockpit
159	/// plugin opens a pane running this shim, which resolves the spawn plan *here*,
160	/// on the executing host, and `exec`s it - so the Zellij pane becomes the agent
161	/// itself, with no PANopt wrapper left around it.
162	///
163	/// Two paths, keyed on whether the process has a backing agent config:
164	///
165	/// - **Agent-backed** (`agent_tool_id` set): look up the config's `tool_type`,
166	///   render its profile's spawn template (`build_launch`) against host-local
167	///   facts (this binary's path, the on-disk token, the daemon host/port). The
168	///   resolution must happen on this host - the daemon can't know our binary
169	///   path or token for a remote pane - which is why the interpreter runs at the
170	///   edge rather than in the daemon. The pid is reported back *before* the
171	///   `exec` (the pid survives `exec`, so the agent inherits it), which flips the
172	///   row `starting -> running`.
173	/// - **Bare** (no config): run the row's `command` via the shell, or an
174	///   interactive shell for a command-less terminal row. Unchanged behavior.
175	///
176	/// Rerunning the exited pane through Zellij re-runs this shim, which re-fetches
177	/// and re-execs.
178	pub fn exec_entry(ws: Option<PathBuf>, id: u64, port: u16) -> Result<()> {
179	    daemon::ensure(None, port)?;
180	    let client = Client::connect(&observer_url(ws.clone(), port)?)?;
181	    let entry = client.call("process_get", json!({ "process_id": id }));
182	    let entry = match entry {
183	        Ok(e) => e,
184	        Err(e) => {
185	            client.close();
186	            return Err(e).with_context(|| format!("looking up process #{id}"));
187	        }
188	    };
189	
190	    if let Some(tool_id) = entry["agent_tool_id"].as_u64() {
191	        return exec_agent_instance(client, &entry, id, tool_id, ws, port);
192	    }
193	    client.close();
194	
195	    let command = entry["command"].as_str().unwrap_or("").trim().to_string();
196	    let cwd = entry["cwd"].as_str().unwrap_or("").trim().to_string();
197	
198	    // A process with no command is a bare terminal: run an interactive shell.
199	    let mut cmd = if command.is_empty() {
200	        Command::new(std::env::var("SHELL").unwrap_or_else(|_| "/bin/sh".to_string()))
201	    } else {
202	        let mut c = Command::new("/bin/sh");
203	        c.arg("-c").arg(&command);
204	        c
205	    };
206	    if !cwd.is_empty() {
207	        cmd.current_dir(&cwd);
208	    } else if let Some(ws) = ws {
209	        cmd.current_dir(ws);
210	    }
211	    let err = cmd.exec();
212	    Err(err).context("could not start the process's command")
213	}
