215	/// Resolve and exec an agent-backed instance (the `agent_tool_id` branch of
216	/// [`exec_entry`]). Consumes `client` so the daemon session is closed before the
217	/// `exec` replaces this process image.
218	fn exec_agent_instance(
219	    client: Client,
220	    entry: &Value,
221	    id: u64,
222	    tool_id: u64,
223	    ws: Option<PathBuf>,
224	    port: u16,
225	) -> Result<()> {
226	    // The config supplies the profile key; the row supplies the per-instance
227	    // identity (copied from the config at start, so edits don't perturb us).
228	    let config = client.call("agent_tool_get", json!({ "agent_tool_id": tool_id }));
229	    let report = |pid: u32| {
230	        // Best-effort: report the pid (which survives the exec below) so the
231	        // daemon flips the row to `running`. A failure here just leaves the row
232	        // `starting`; it must not block the spawn.
233	        let _ = client.call("process_report", json!({ "process_id": id, "pid": pid }));
234	    };
235	    let config = match config {
236	        Ok(c) => c,
237	        Err(e) => {
238	            client.close();
239	            return Err(e).with_context(|| format!("looking up agent config #{tool_id}"));
240	        }
241	    };
242	    let tool_type = config["tool_type"].as_str().unwrap_or("").to_string();
243	
244	    let ws_path = resolve_ws(ws)?;
245	    let token = panopt_core::auth::read_token(&paths::token()?)
246	        .context("reading the panopt token (start the daemon with `panopt up`)")?;
247	    let panopt_bin = std::env::current_exe()
248	        .context("looking up panopt's own path for the agent's MCP config")?;
249	    let host = std::env::var("PANOPT_HOST").unwrap_or_else(|_| "127.0.0.1".into());
250	    // The row's name is the stable agent id (copied from the config); fall back
251	    // to a synthetic id only if a row somehow has no name.
252	    let agent_id = entry["name"]
253	        .as_str()
254	        .filter(|s| !s.is_empty())
255	        .map(str::to_string)
256	        .unwrap_or_else(|| format!("agent-{id}"));
257	    let name = entry["display_name"]
258	        .as_str()
259	        .filter(|s| !s.is_empty())
260	        .unwrap_or(&agent_id)
261	        .to_string();
262	
263	    let profiles = ProfileSet::load().context("loading agent-type profiles")?;
264	    let profile = profiles.get(&tool_type).ok_or_else(|| {
265	        anyhow::anyhow!("agent config #{tool_id} names unknown agent type '{tool_type}'")
266	    })?;
267	
268	    let facts = Facts {
269	        panopt_bin: panopt_bin.to_string_lossy().into_owned(),
270	        host,
271	        port,
272	        ws: ws_path.to_string_lossy().into_owned(),
273	        project: project_identity::resolve(&ws_path).key,
274	        agent_id,
275	        name,
276	        token,
277	        model: profile.default_model.clone(),
278	    };
279	    let dir = paths::instance_dir(id)?;
280	    let launch = build_launch(profile, &facts, &dir)
281	        .with_context(|| format!("rendering the spawn plan for process #{id}"))?;
282	
283	    report(std::process::id());
284	    client.close();
285	
286	    let (program, rest) = launch
287	        .argv
288	        .split_first()
289	        .context("the resolved spawn plan has an empty argv")?;
290	    let mut cmd = Command::new(program);
291	    cmd.args(rest);
292	    cmd.envs(&launch.env);
293	    let cwd = entry["cwd"].as_str().unwrap_or("").trim();
294	    if !cwd.is_empty() {
295	        cmd.current_dir(cwd);
296	    } else {
297	        cmd.current_dir(&ws_path);
298	    }
299	    let err = cmd.exec();
300	    Err(err).with_context(|| format!("could not exec the agent ({})", program.clone()))
301	}
