#[test]
fn tick_process_projections_refreshes_idle_for_active_agents() {
    let mut fx = Fixture::new();
    let (p, root) = fx.project("proj");
    let config = fx
        .store
        .agent_tool_create(
            p,
            "claude-a".into(),
            "Mediator".into(),
            "claude".into(),
            "/work".into(),
            "claude-code".into(),
            true,
        )
        .unwrap();
    let started = fx.store.process_start(p, config).unwrap();
    // Flip it to running so it counts as a live agent for the tick.
    fx.store
        .process_report(p, started.id, Some(4242), None, None)
        .unwrap();

    // Register the agent in the coordination registry under its instance
    // name so the `idle:` join (by name) finds it, then backdate its
    // last_seen so the age is a non-zero number of whole minutes.
    fx.store
        .registry
        .touch(p.0, "agentkey", crate::model::KeySource::Declared);
    fx.store
        .agent_identify(p, "agentkey", "claude-a".into(), None)
        .unwrap();
    fx.store.registry.test_backdate_last_seen(
        p.0,
        "agentkey",
        std::time::Duration::from_secs(180),
    );

    let count = fx.store.tick_process_projections().unwrap();
    assert_eq!(count, 1, "one project has a live agent");
    let md = std::fs::read_to_string(root.join(".panopt/processes.md")).unwrap();
    assert!(md.contains("idle:3m"), "idle age not refreshed:\n{md}");

    // A project with no live agent is skipped (no work, no panic).
    let (_q, _) = fx.project("empty");
    assert_eq!(fx.store.tick_process_projections().unwrap(), 1);
}

